    "year": "2018-2019",
    "q_num": 28,
    "subject": "Biyofizik",
    "professor": "Belirtilmemiş",
    "question": "Eksitabl hücre zarlarında aksiyon potansiyelinin depolarizasyon fazından sorumlu olan voltaj kapılı sodyum (Na+) kanallarının kapı yapıları ve durumları ile ilgili hangisi doğrudur?",
    "options": [
      {
        "letter": "A",
        "text": "Repolarizasyonda sodyum kanalları dışarıya Na+ pompalar."
      },
      {
        "letter": "B",
        "text": "Dinlenim durumunda her iki kapı da tamamen açıktır."
      },
      {
        "letter": "C",
        "text": "Depolarizasyon sırasında inaktivasyon kapısı derhal açılır."
      },
      {
        "letter": "D",
        "text": "Dinlenim durumunda aktivasyon kapısı kapalı, inaktivasyon kapısı açıktır."
      },
      {
        "letter": "E",
        "text": "Mutlak refrakter dönemde aktivasyon kapısı kapanamamıştır."
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Uyarılabilir (eksitabl) hücre zarlarındaki voltaj kapılı Na⁺ kanalları dinlenim membran potansiyelinde (-70 ila -90 mV) dış taraftaki **aktivasyon (m) kapısı kapalı**, hücre içi taraftaki **inaktivasyon (h) kapısı açık** durumdadır; zar eşik değere depolarize olduğunda aktivasyon kapısı hızla açılarak Na⁺ girişini başlatır (D doğru). Repolarizasyon fazında sodyum kanalları hücre dışına Na⁺ pompalamaz; sodyum kanalları inaktivasyon kapısıyla kapanırken voltaj kapılı K⁺ kanalları açılarak dışarı K⁺ çıkışı sağlanır (Na⁺ dışa pompalanması Na⁺/K⁺-ATPaz pompasıyla yapılır) (A yanlış). Dinlenim durumunda her iki kapı açık olsaydı Na⁺ sürekli hücre içine akardı ve dinlenim potansiyeli korunamazdı; dinlenimde aktivasyon kapısı kapalıdır (B yanlış). Depolarizasyon sırasında derhal açılan kapı inaktivasyon kapısı değil **aktivasyon kapısı**dır; inaktivasyon kapısı ise milisaniyeler içinde kapanarak sodyum akımını sonlandırır (C yanlış). Mutlak refrakter dönemde yeni bir uyarının aksiyon potansiyeli oluşturamamasının nedeni aktivasyon kapısının kapanamaması değil, **inaktivasyon kapısının kapalı kilitli kalması** ve zar repolarize olana dek yeniden açılamamasıdır (E yanlış).",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
