    "question": "soru: Hücre duvan sentezinde N-asetil muramik astte bağlı zincirinde yer alan son iki D-AIanm molekülüM bağlanarak çapraz oluşumunu engelleyen anüm1KrobıyaI aşağıdakilerden hangts\"lr?",
