    "professor": "Belirtilmemiş",
    "question": "İşitme ve denge kaybı (ototoksisite) ile böbrek yetmezliği (nefrotoksisite) yan etkileri ile başvuran bir hastada bu tabloya yol açma olasılığı en yüksek olan antibiyotik grubu hangisidir?",
    "options": [
      {
        "letter": "A",
        "text": "Penisilin V"
      },
      {
        "letter": "B",
        "text": "Siprofloksasin"
      },
      {
        "letter": "C",
        "text": "Eritromisin"
      },
      {
        "letter": "D",
        "text": "Gentamisin (Aminoglikozitler)"
      },
      {
        "letter": "E",
        "text": "Amoksisilin"
      }
    ],
