    "professor": "Belirtilmemiş",
    "question": "Su molekülünün (H2O) canlılar için hayati öneme sahip fiziksel ve kimyasal özellikleri ile ilgili aşağıdaki ifadelerden hangisi doğru değildir?",
    "options": [
      {
        "letter": "A",
        "text": "Molekülleri arasındaki hidrojen bağları sayesinde yüksek kohezyon ve yüzey gerilimi gösterir."
      },
      {
        "letter": "B",
        "text": "Polar (dipol) karakteri sayesinde iyonik ve polar bileşikleri kolayca çözer."
      },
      {
        "letter": "C",
        "text": "Yüksek kaynama ve buharlaşma ısısına sahiptir."
      },
      {
        "letter": "D",
        "text": "Su, diğer benzer molekül ağırlıklı sıvılara göre daha düşük özgül ısı kapasitesine sahiptir."
      },
      {
        "letter": "E",
        "text": "Katı haldeki yoğunluğu (buz) sıvı haldeki yoğunluğundan düşüktür."
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Su, yapısındaki yaygın hidrojen bağları ağı nedeniyle molekül ağırlığına kıyasla son derece **yüksek bir özgül ısı kapasitesine** (1 cal/g·°C) sahiptir; bu yüksek kapasite sayesinde canlılarda vücut sıcaklığının çevresel ani ısı dalgalanmalarına karşı korunmasında kritik bir termal tampon görevi görür.",
