    "q_num": 46,
    "subject": "Anatomi",
    "professor": "Belirtilmemiş",
    "question": "Aksiyon potansiyelinin presinaptik uca ulaşması ve kimyasal sinaptik iletinin gerçekleşmesi sırasında olayların doğru kronolojik sıralaması hangi seçenektir?\nI. Presinaptik terminalin depolarizasyonu ile voltaj kapılı Ca2+ kanallarının açılması ve hücre içine Ca2+ girişi\nII. Sinaptik veziküllerin ekzositoz ile nörotransmitterleri sinaptik aralığa boşaltması\nIII. Nörotransmitterin postsinaptik membrandaki reseptörüne bağlanarak iyon kanallarını açması",
    "options": [
      {
        "letter": "A",
        "text": "II — I — III"
      },
      {
        "letter": "B",
        "text": "III — I — II"
      },
      {
        "letter": "C",
        "text": "I — III — II"
      },
      {
        "letter": "D",
        "text": "I — II — III"
      },
      {
        "letter": "E",
        "text": "II — III — I"
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Kimyasal sinapsta aksiyon potansiyeli presinaptik uca vardığında: (I) Zar depolarize olarak voltaj kapılı Ca²⁺ kanalları açılır ve hücre içine Ca²⁺ girer; (II) Artan Ca²⁺ sinaptik veziküllerin ekzositozunu tetikler ve nörotransmitter sinaptik aralığa boşalır; (III) Nörotransmitter postsinaptik reseptörlere bağlanarak iyon kanallarını açar (I — II — III).",
    "note": "Hatırlanan 4 şıklı sorudan 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
    "q_type": "mcq",
    "incomplete": false,
