    "explanation": "Bu soru kaydında soru kökü OCR sırasında atış hedefi sorusuyla karışmış olup seçenekler membran elektrofizyolojisine aittir; E seçeneğindeki **normal vücut sıcaklığında tek değerlikli bir iyonun denge potansiyelini (`±61 mV log([C]d/[C]i)`) hesaplamak için kullanılan eşitlik Gibbs-Donnan değil Nernst eşitliğidir**, Gibbs-Donnan dengesi ise zardan geçemeyen yüklü makromoleküller varlığında difüzyonel iyonların zıt taraflardaki konsantrasyon oranlarının eşitliğini açıklar ve bu hatalı eşleştirme nedeniyle anahtarda E seçeneği işaretlenmiştir (E yanlış). Donnan dengesi sağlandığında zardan serbestçe geçebilen tüm difüzyonel iyonların kimyasal ve elektriksel potansiyel dengeleri ortak bir zar potansiyelinde birleştiğinden Nernst denge potansiyelleri birbirine eşit olur (A doğru). Nernst denklemi ortamda birden fazla geçirgen iyon bulunduğunda hepsinin etkisini eşit varsaymaz; yalnızca tek bir iyonun denge potansiyelini hesaplar, çoklu iyon katkısını ise geçirgenliklerle ağırlıklandıran Goldman-Hodgkin-Katz modeli ele alır (B yanlış). Goldman-Hodgkin-Katz (soruda Hodgkin-Huxley-Katz) modeli, Nernst denkleminden farklı olarak hücre zarının farklı iyonlara gösterdiği görece geçirgenlik katsayılarını da hesaba katar (C doğru). Nernst denklemi, iyonun derişim farkından kaynaklanan kimyasal potansiyel gradyentini tam olarak dengeleyecek karşıt elektriksel potansiyel farkını gösterir (D doğru).",
