    "question": "Hücre membranının elektriksel eş devre modelinde dinlenim membran potansiyeli ve iyonik akımlar hesaplanırken akım (I), voltaj (V) ve iletkenlik (g) arasındaki ilişki hangi temel fizik yasası ile ifade edilir?",
