    "answer": "E",
    "open_answer": "",
    "explanation": "**Kimyasal sinapslarda** presinaptik terminalden Ca²⁺ aracılı ekzositozla sinaptik yarığa salınan nörotransmitter molekülleri aracı faktör olarak görev yapar ve postsinaptik zardaki özgül reseptörlere bağlanarak uyarıyı iletir (E doğru). Kimyasal sinapslarda Ca²⁺ girişi, vezikül füzyonu, yarıktan difüzyon ve reseptör bağlanması zaman aldığı için yaklaşık 0,5 ms'lik **sinaptik gecikme mutlaka görülür**; gecikmenin ihmal edilebilir olduğu sinapslar elektriksel sinapslardır (A yanlış). Elektriksel sinapslar sitoplazmaları doğrudan birleştiren düşük dirençli kanallar içerdiğinden iyon akışı çoğunlukla **çift yönlü** gerçekleşir; tek yönlü ileti kimyasal sinapslara özgüdür (B yanlış). İki komşu hücre zarının **gap junction (neksus)** kanallarıyla fiziksel olarak birleştiği yapı kimyasal sinaps değil **elektriksel sinaps**tır (C yanlış). Yaklaşık 0,5 ms süren belirgin sinaptik gecikme elektriksel sinapslarda değil nörotransmitter salınımı gerektiren **kimyasal sinapslarda** görülür (D yanlış).",
