    "open_answer": "",
    "explanation": "**Fas (CD95 / APO-1)** ve TNF reseptörleri hücre zarında bulunan ölüm reseptörleridir; Fas ligandının (FasL) bağlanmasıyla prokaspaz-8'i aktive ederek apoptozu içsel değil, **ekstrinsik (dışsal) yolaktan** başlatırlar.",
