    "professor": "Rahşan Ilıkçı Sağkan",
    "question": "soru: Aşağıdaki moleküllerden hangisi ile adherens bağlantılarda kaderinler aktin filamentlerine bağlanırlar?",
    "options": [
      {
        "letter": "A",
        "text": "kateninler Doğru Seçenek"
      },
      {
        "letter": "B",
        "text": "dezmoglein"
      },
      {
        "letter": "C",
        "text": "dezmokolin"
      },
      {
        "letter": "D",
        "text": "spektrin"
      },
      {
        "letter": "E",
        "text": "vinkulin moleküllerin taşınmasında aşağıdakilerden hangisi"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Adherens bağlantılarda (zonula adherens), transmembran adezyon molekülleri olan E-kaderinlerin sitoplazmik kuyrukları, hücre içi adaptör proteinler olan **kateninler (alfa ve beta-katenin)** aracılığıyla hücre iskeletinin aktin mikrofilamanlarına bağlanır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
