    "q_num": 23,
    "subject": "Tıbbi Genetik",
    "professor": "Aynur Karadağ",
    "question": "soru: Aşağıdakilerden hangisi nükleer lamina için söylenemez?",
    "options": [
      {
        "letter": "A",
        "text": "Çekirdek membranında çok sayıda nukleus porları yer alır."
      },
      {
        "letter": "B",
        "text": "Dış zarı kuşatan filamentler az organize olmuş iken iç zarın için fibröz bir ağ şeklinde kuşatan fılamentler oldukça düzgün sıralanmıştır."
      },
      {
        "letter": "C",
        "text": "Lamin tabakası iç zar ile kromatin arasındaki ilişkiyi sağlar."
      },
      {
        "letter": "D",
        "text": "Lamin B, nükleer zarf dağıldıktan sonra oluşan zar veziküllerine bağlı olarak kalır."
      },
      {
        "letter": "E",
        "text": "Mitoz bölünme sırasında Lamin A ve C fosforlanır ve nükleus zarı parçalanırken zara bağlı olarak kalırlar."
      }
    ],
    "answer": "E",
