    "question": "soru: Hücre döngüsü kontrol basamakları için hangisi söylenemez?",
    "options": [
      {
        "letter": "A",
        "text": "Kontrol noktalarının görevi, tamamlanmamış veya hasarlı kromozomların replikasyonunu engellemek ve bunların yavru hücrelere geçişini önlemektir."
      },
      {
        "letter": "B",
        "text": "GI -b S fazı, metafaz -ş anafaz, ve anafaz -ş telofaz ve sitokinez geri dönüşümsüzdür."
      },
      {
        "letter": "C",
        "text": "Kontrol noktaları mayalarda besin varlığına göre denetlenirken hayvan hücrelerinde hücre dışı büyüme faktörleri tarafından denetlenir."
      },
      {
        "letter": "D",
        "text": "G2 aşamasında hasarlı DNA'nın S evresine girmeden onarılabilmesini sağlanır."
      },
      {
        "letter": "E",
        "text": "M kontrol noktası kromozomların mitotik iğ üzerinde düzenli bir şekilde yer almalarını kontrol eder."
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Hücre döngüsünde **G1 kontrol noktası (G1/S)** hasarlı DNA'nın S fazına (DNA replikasyonuna) girmesini engeller ve onarılmasını sağlar. **G2/M kontrol noktası** ise S fazı sonrasında replikasyonu tamamlanmamış veya hasarlı DNA taşıyan hücrelerin mitoza (M fazına) girmesini bloke eder.",
    "note": "",
