    "professor": "Rahşan Ilıkçı Sağkan",
    "question": "soru: Hızlı bir büyüme periyodunun hemen arkasından dağılan bir mikrotübül gözlenmektedir. Bu kırılmanın uyarılması için bu özel mikrotübülün başına aşağıdakilerden hangisi gelmiş olabilir?",
    "options": [
      {
        "letter": "A",
        "text": "Dynein tarafından bağlanma - Öğrencinin işaretlediği"
      },
      {
        "letter": "B",
        "text": "ATP başının oluşumu"
      },
      {
        "letter": "C",
        "text": "G TP başının kaybı"
      },
      {
        "letter": "D",
        "text": "Gelsolin ile şiddetlenme"
      },
      {
        "letter": "E",
        "text": "Kofilin ile bükülme"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Mikrotübüllerin artı (+) ucundaki beta-tübülin birimlerine bağlı GTP, mikrotübülün kararlılığını sağlayan bir **GTP başlığı (GTP cap)** oluşturur. GTP başlığının hidroliz veya ayrılma sonucu kaybı, protofilamanların hızla geriye doğru kıvrılıp açılmasına ve mikrotübülün aniden depolimerize olmasına yol açar.",
    "note": "",
