    "explanation": "Bakteriler arasında doğal yatay gen transferi mekanizmalarından **transdüksiyon**, verici ve alıcı bakteri hücreleri arasında doğrudan fiziksel temas olmaksızın bir **bakteriyofaj (bakteri virüsü)** aracılığıyla genetik materyalin aktarılması olayıdır (A doğru). Çözünmüş serbest DNA moleküllerinin dış ortamdan alıcı bakteri tarafından doğrudan hücre içine alınması transdüksiyon değil **transformasyon**dur (B yanlış). Özellikle litik bakteriyofajların aracılık ettiği transdüksiyonda konak verici bakteri hücresi faj çoğalması sonunda parçalanır, hep sağlam kalmaz (C yanlış). Transfer (tra) genlerinin kodladığı seks pilusu aracılığıyla doğrudan hücre temasıyla gerçekleşen aktarım **konjugasyon**dur (D yanlış). Generalize transdüksiyonda bakteriyofaj içine bakteri kromozomuna ait DNA parçaları da rastgele paketlenip aktarılabildiği için süreç yalnızca ekstra kromozomal plazmitlerle sınırlı değildir (E yanlış).",
