    "professor": "Hüseyin Haydar Kutlu",
    "question": "Metisiline dirençli Staphylococcus aureus (MRSA) suşlarının neden olduğu ciddi enfeksiyonların tedavisinde aşağıdaki antibiyotiklerden hangisi/hangileri kullanılabilir?\nI. Vankomisin\nII. Linezolid\nIII. Daptomisin\nIV. Standart Ampisilin",
