    "explanation": "**İrreversibl inhibisyonda** (örneğin aspirin ile COX veya organofosfatlarla asetilkolinesteraz inhibisyonu) inhibitör ile enzimin aktif bölgesi arasında **kalıcı kovalent bağ** oluşur ve enzim aktivitesi geri dönüşümsüz biçimde kaybolur (C doğru). İnhibitörün substrattan farklı bir yere ve **daima ES (enzim-substrat) kompleksine** bağlanması irreversibl inhibisyonu değil reversibl **unkompetitif** inhibisyonu tanımlar (A yanlış). Hem `Vmax` hem de `Km` değerinin aynı oranda azaldığı kinetik desen **unkompetitif** inhibisyona özgüdür; irreversibl inhibisyonda `Vmax` düşerken kalan sağlam enzimlerin `Km`'i değişmez (B yanlış). İrreversibl inhibisyonda serbest enzim-inhibitör ayrışma dengesi kurulmadığı için reversibl inhibisyonlardaki klasik denge kinetik özellikleri geçerli değildir (D yanlış). İrreversibl inhibisyon enzimin substratına olan ilgisini artırmaz; sağlam kalan enzim fraksiyonunun substrat afinitesi sabit kalırken toplam aktif enzim havuzu azalır (E yanlış).",
