    "explanation": "**Transdüksiyon**, verici ve alıcı bakteri hücreleri arasında fiziksel temas gerektirmeksizin bir **bakteriyofaj** aracılığıyla bakteri DNA'sının bir hücreden diğerine taşınması mekanizmasıdır (A doğru). Genetik materyalin ortamdan serbest çözünmüş DNA olarak alınması transdüksiyon değil **transformasyon** olarak adlandırılır (B yanlış). Litik döngülü fajların aracılık ettiği transdüksiyon sürecinde enfekte edilen verici bakteri lizise uğrar, her zaman sağlam kalmaz (C yanlış). `Tra` genleri ve seks pilusu ile kurulan temaslı gen aktarımı transdüksiyon değil **konjugasyon**dur (D yanlış). Fajlar bakteri kromozomunun farklı bölgelerinden parçaları paketleyip aktarabileceği için transdüksiyon sadece ekstra kromozomal DNA'ya özgü değildir (E yanlış).",
