    "question": "Hemodinamik ve akışkanlar mekaniği ile ilgili olarak aşağıdakilerden hangileri YANLIŞTIR?\nI. Süreklilik yasasına göre debi yarıçapla orantılı olarak artar.\nII. Viskoz kuvvet akışı sürdürücü kuvvettir.\nIII. Kan basıncının oskültasyonla ölçümünde laminer akış Korotkoff seslerini oluşturur.",
