    "question": "Termodinamik ve biyolojik sistemler ile ilgili aşağıdaki ifadelerden hangileri YANLIŞTIR?\nI. Termodinamik denge durumunda sistemin entropisi minimumdur.\nII. Bir sistem daima en yüksek entalpi ve en düşük entropiye sahip olmak eğilimindedir.",
