    "subject": "Anatomi",
    "professor": "Belirtilmemiş",
    "question": "Elektrik ve biyoelektromanyetizma ile ilgili aşağıdaki ifadelerden hangileri yanlıştır?\nI. Bir maddenin dielektrik sabiti ne kadar yüksekse o kadar iyi iletkendir.\nII. Bir iletkenin kesit alanı (kalınlığı) arttıkça elektriksel direnci artar.",
