    "question": "Elektrik ve biyolojik elektromanyetizma ile ilgili aşağıdaki ifadelerden hangileri yanlıştır?\nI. Dielektrik sabiti yüksek maddeler iyi elektriksel iletkendir.\nII. İletkenin kesit alanı arttıkça direnci artar.\nIII. Kalpteki biyoelektriksel olayların yarattığı manyetik alan beyindeki manyetik alandan çok daha küçüktür.",
