    "question": "Hücre zarından maddelerin taşınmasında konsantrasyon farkı artışı ile taşınma hızı arasındaki ilişki grafiği incelendiğinde; basit difüzyon doğrusal artarken, kolaylaştırılmış difüzyonun belirli bir konsantrasyondan sonra plato çizmesinin (doygunluğa ulaşmasının) nedeni nedir?",
