    "professor": "Belirtilmemiş",
    "question": "Nöron hücre iskeleti elemanları ile ilgili olarak aşağıdakilerden hangileri YANLIŞTIR?\nI. Mikrotübüller hücre iskeletinin en stabil kemikleri olup asla dinamik polimerizasyon-depolimerizasyon göstermezler.\nII. Nörofilamentler nöronun en kalın hücre iskeleti yapılarıdır (en kalın mikrotübüllerdir).",
