    "question": "Nöronlarda iyon kanallarının dağılımı ile ilgili olarak aşağıdakilerden hangileri YANLIŞTIR?\nI. Kv7 potasyum kanalları internodal segmentte yoğunlaşmıştır.\nII. Juxtaparanodal bölgede voltaj kapılı sodyum kanal yoğunluğu en fazladır (Ranvier düğümünde en fazladır).",
