    "subject": "Temel Tıp Bilimleri",
    "professor": "Belirtilmemiş",
    "question": "Bir sinir, elektriksel olarak uyarılarak, uyarma noktasından yaklaşık 10 cm uzaklıktan bileşik aksiyon gözleniyor. Oslloşkopta latans 2,4 ms Okunuyor. Uyaran şiddeti uyarma noktası aynı kalmak koşulu 110 gözlem elektrotları 5 cm daha uzaklaştırıldığında, latans 3,4 olarak Okunuyor. Bu sinirde İletim hm ne kadardır?",
    "options": [
      {
        "letter": "A",
        "text": "20"
      },
      {
        "letter": "B",
        "text": "50 Seçenek"
      },
      {
        "letter": "C",
        "text": "65"
      },
      {
        "letter": "D",
        "text": "75"
      },
      {
        "letter": "E",
        "text": "85 mis"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "İletim hızı v = Δx / Δt formülüyle bulunur; elektrot 5 cm (0,05 m) uzaklaştırıldığında latans farkı Δt = 3,4 - 2,4 = 1,0 ms (0,001 s) olduğuna göre sinir iletim hızı 0,05 / 0,001 = **50 m/s**dir.",
    "note": "",
