    "professor": "Belirtilmemiş",
    "question": "TBSoru:lskclot kasında gorilmo kuvvctlylo (Şok\") llglll olarak hangisi doğrudur? c",
    "options": [
      {
        "letter": "A",
        "text": "A da en büyüktür"
      },
      {
        "letter": "B",
        "text": "B de en büyüktür.thğru Seçenek"
      },
      {
        "letter": "C",
        "text": "C de en"
      },
      {
        "letter": "D",
        "text": "B Ve C de aynıdır"
      },
      {
        "letter": "E",
        "text": "A ve B aynıdgr"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "İskelet kasında sarkomer uzunluğu-gerilim (uzunluk-gerim) eğrisinde en büyük aktif kasılma kuvveti, aktin ve miyozin filamentlerinin maksimum sayıda çapraz köprü oluşturacak şekilde ideal örtüşme sağladığı plato bölgesindeki **B noktasında** (~2.0–2.2 µm sarkomer uzunluğu) üretilir (B doğru). Eğrinin başlangıçtaki **A noktasında** sarkomer boyu optimumun altında (aşırı kısalmış) olduğundan ince aktin filamentleri karşı tarafla ve Z diskleriyle çakışarak çapraz köprü etkinliğini düşürür, bu nedenle kuvvet B'deki kadar büyük değildir (A yanlış). Eğrinin inen kolundaki **C noktasında** sarkomer aşırı gerilmiş durumda olduğundan kalın ve ince filamentler arasındaki örtüşme azalır ve üretilen kasılma kuvveti B noktasına göre belirgin şekilde düşer (C yanlış). B noktası optimum örtüşmeye karşılık gelen maksimum gerim platosu iken C noktası aşırı gerilme nedeniyle kuvvetin düştüğü bölge olduğundan B ve C noktalarındaki kuvvetler eşit değildir (D yanlış). A noktası filament sıkışmasının yaşandığı düşük kuvvet bölgesinde, B noktası ise maksimum örtüşme bölgesinde yer aldığından A ve B noktalarındaki kasılma kuvvetleri aynı değildir (E yanlış).",
    "note": "",
