    "subject": "Biyokimya",
    "professor": "Soycan Mızrak",
    "question": "Aşağıdaki aminoasitlerden hangisi nötral pHda yan grupları tamamen iyonize olarak negatif (-) yüke sahiptir?",
    "options": [
      {
        "letter": "A",
        "text": "Prolin"
      },
      {
        "letter": "B",
        "text": "Alanin"
      },
      {
        "letter": "C",
        "text": "Aspartat"
      },
      {
        "letter": "D",
        "text": "Tirozin"
      },
      {
        "letter": "E",
        "text": "Fenilalanin"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Yan zincirinde pKa değeri yaklaşık 3.9 olan serbest bir karboksil grubu (-COOH) taşıyan **Aspartat (Aspartik asit)**, fizyolojik ve nötral pH'da (~7.4) bu protonunu tamamen kaybedip karboksilat (-COO⁻) haline geçerek **net negatif (-) yüke** sahip olur.",
    "note": "",
