    "explanation": "Çizgili kas ve beyin dokusunda yüksek konsantrasyonda bulunan, fizyolojik bir hücre içi proton tamponu ve antioksidan olan **karnozin**, beta-alanin ile L-histidin aminoasitlerinin peptid bağı kurmasıyla oluşan bir **dipeptittir (beta-alanil-L-histidin)**.",
