    "explanation": "**Glutatyon (GSH)**, yapısındaki sistein kalıntısının reaktif tiyol (-SH) grubu sayesinde hücre içi hidrojen peroksit ve serbest radikalleri indirgeyen, gamma-glutamil-sisteinil-glisin yapısındaki güçlü **fizyolojik tripeptit antioksidandır**.",
