    "explanation": "Mikroskobun optik ayırma gücü (çözünürlük sınırı); Abbe denklemine göre ışığın dalga boyu, ortamın kırma indisi ve objektifin sayısal açıklığına (NA) bağlıdır. **Oküler** yalnızca objektifin oluşturduğu görüntüyü büyütür, mikroskobun çözünürlüğüne etki etmez.",
