    "professor": "Hasan Asker",
    "question": "Steroid sentezleyen hücrelerde hangi organel yoğun bir şekilde gözükür?",
    "options": [
      {
        "letter": "A",
        "text": "Düz endoplazma retikulum"
      },
      {
        "letter": "B",
        "text": "Granüllü endoplazma retikulum"
      },
      {
        "letter": "C",
        "text": "Golgi kopmleksi"
      },
      {
        "letter": "D",
        "text": "Mitokondriyon"
      },
      {
        "letter": "E",
        "text": "Ribozomlar"
      }
    ],
