    "explanation": "Bakteri üreme eğrisinde (lag, log, durağan, ölüm); besin maddelerinin tükenmesi ve toksik metabolitlerin birikmesiyle yeni bölünen bakteri sayısının ölen bakteri sayısına eşitlendiği ve popülasyon yoğunluğunun sabit kaldığı dönem **Durağan (stasyoner) dönemdir**.",
