    "explanation": "Bakterilerde de novo folik asit sentez yolundaki dihidropteroat sentaz ve dihidrofolat redüktaz enzimlerini ardışık olarak bloke eden kombine antimikrobiyal ajan **Trimetoprim-sülfametoksazol**'dür; bu enzimlerde mutasyon geliştiğinde ilaca direnç ortaya çıkar.",
