    "explanation": "Kardiyak aksiyon potansiyelinde sinoatriyal düğümün depolarizasyon fazının (Faz 0, Y dönemi) sonunda ve ventrikül miyositinin plato fazının (Faz 2, C dönemi) sonunda voltaj kapılı L-tipi Ca²⁺ kanalları inaktivasyona uğrayarak repolarizasyon fazı başlatılır.",
