    "q_num": 65,
    "subject": "Biyofizik",
    "professor": "Serçin Özlem Çalışkan",
    "question": "Geçirgenlik oranları PK : PNa = 0.2 : 1 olan iyonların oluşturduğu zar  potansiyelinin değeri nedir? (İçK,Na konsantrasyonları (mM): 120, 10; Dış K,Na konsantrasyonları (mM): 5, 140)",
    "options": [
      {
        "letter": "A",
        "text": "-37,9"
      },
      {
        "letter": "B",
        "text": "+45,4"
      },
      {
        "letter": "C",
        "text": "+37,9"
      },
      {
        "letter": "D",
        "text": "-45,4"
      },
      {
        "letter": "E",
        "text": "+61,5"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Goldman-Hodgkin-Katz eşitliğine göre Vm = 61,5 log₁₀[(0,2×5 + 1×140) / (0,2×120 + 1×10)] = 61,5 log₁₀(141 / 34) ≈ 61,5 × 0,6177 ≈ **+37,9 mV** olarak hesaplanır.",
