    "professor": "Serçin Özlem Çalışkan",
    "question": "Ventrikül kasında gerçekleşen plato evresinin nedeni aşağıdakilerden hangisidir?",
    "options": [
      {
        "letter": "A",
        "text": "K+ çıkışı"
      },
      {
        "letter": "B",
        "text": "Ca+2 girişi ve K+ çıkışı arasındaki denge"
      },
      {
        "letter": "C",
        "text": "Ca+2 girişi"
      },
      {
        "letter": "D",
        "text": "Ca+2 ve Na+ girişi arasındaki denge"
      },
      {
        "letter": "E",
        "text": "Na+ girişi"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "Kardiyak ventrikül miyositlerinde aksiyon potansiyelinin Faz 2 (plato) evresi; L-tipi voltaj kapılı kanallardan **hücre içine yavaş Ca²⁺ girişi** ile gecikmiş doğrultucu potasyum kanallarından **hücre dışına K⁺ çıkışının** elektriksel olarak birbirini dengelemesi sonucu oluşur.",
    "note": "",
