    "q_num": 70,
    "subject": "Biyofizik",
    "professor": "Serçin Özlem Çalışkan",
    "question": "İyon-dipol etkileşimleri ile ilgili verilen aşağıdaki yargılarından hangisi/hangileri doğrudur?I. Bu etkileşimin olabilmesi için maddelerden birinin iyonik yani iyon verebilen diğerinin ise polar olması gerekir.II. Atom ve moleküller arası etkileşimlerden güçlü olan etkileşimler sınıfındadır.III. Bu etkileşimde, iki molekül arasındaki uzaklığın altıncı kuvveti ile ters orantılıdır.",
    "options": [
      {
        "letter": "A",
        "text": "I, II, III"
      },
      {
        "letter": "B",
        "text": "II, III"
      },
      {
        "letter": "C",
        "text": "Yalnız I"
      },
      {
        "letter": "D",
        "text": "Yalnız II"
      },
      {
        "letter": "E",
        "text": "I, III"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "İyon-dipol etkileşimi, tam yüklü bir iyon (Na⁺, Cl⁻) ile polar bir molekülün (H₂O) kalıcı dipolü arasında meydana gelir (I doğru); iyonik veya kovalent bağlar gibi güçlü kimyasal bağlar değil zayıf fiziksel etkileşimler sınıfındadır ve uzaklığın karesi ile ters orantılıdır (yalnız I doğrudur).",
