    "subject": "Tıbbi Genetik",
    "professor": "Aynur Karadağ",
    "question": "Aşağıdakilerden hangisi hücre ölümü için doğru olarak tanımlanmıştır?",
    "options": [
      {
        "letter": "A",
        "text": "Apoptotik hücre ölümünde apoptotik cisimcikler makrofajlar tarafından tanınmaz veinflamasyona yol açar."
      },
      {
        "letter": "B",
        "text": "Apoptotik hücre ölümünde enerji gereksinimi yoktur ve ATP harcanmaz."
      },
      {
        "letter": "C",
        "text": "Hücrede antiapoptotik proteinler fazla ise hücre apoptoza eğilimlidir."
      },
      {
        "letter": "D",
        "text": "Nekrotik hücre ölümü patolojik  bir süreçtir ve dokuda inflamasyon oluşturur."
      },
      {
        "letter": "E",
        "text": "Nekrotik hücre ölümünde rasgele DNA kırıkları olmaz ve düzenli kırılma görülür."
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "**Nekrotik hücre ölümü**, şiddetli hipoksi, toksin veya fiziksel travma sonucu hücre zarının parçalanmasıyla gelişen **patolojik bir süreçtir** ve hücre içi içeriğin dokuya dağılmasıyla çevrede belirgin **inflamasyon oluşturur** (D doğru). Apoptozda oluşan apoptotik cisimcikler makrofajlar tarafından hızlıca tanınıp fagosite edildiğinden doku inflamasyonuna yol açmaz (A yanlış). Apoptoz kaspazların aktivasyonu ve hücresel parçalanma için aktif enerji gerektiren, ATP harcanan programlı bir hücre ölümüdür (B yanlış). Bcl-2 gibi antiapoptotik proteinlerin düzeyinin fazla olması apoptozu tetiklemez, tam aksine inhibe ederek hücreyi ölümden korur (C yanlış). Nekrozda DNA düzenli endonükleaz kesimleriyle merdiven paterni göstermez; aksine lizozomal enzimlerle rastgele parçalanır, düzenli DNA kırılması apoptozun özelliğidir (E yanlış).",
