    "explanation": "Aminoasit kalitatif tayinlerinde: Guanidino grubu içeren **Arginin Sakaguchi reaksiyonu** ile kırmızı renk; aromatik halkalı aminoasitler nitrik asitle **Ksantoprotein reaksiyonu** ile sarı renk; sistein ise serbest -SH grubu ile **sodyum nitroprussiat** ile mor-kırmızı renk verir.",
