    "professor": "Soycan Mızrak",
    "question": "Açlık diyeti uygulayan bir erişkinde ilk hafta dallı zincirli amino asitler artar ama sonra tüm aminoasitlerin kan düzeyleri düşmeye başlar. En fazla azalan aminoasit aşağıdakilerden hangisidir?",
