    "professor": "Hatice Bozkurt Yavuz",
    "question": "Peptidleri kısa yazmak için, amino asitlerin üç harfli veya tek harfli simgeleri ile yazılır. Bazen peptid kısımları gösterilebilir.  Buna göre Alanil-glisil-serin aşağıdaki hangi şıkta aynı olarak verilmiştir?",
