    "explanation": "**Homokarnozin**, beyin dokusunda yüksek derişimde bulunan ve gamma-aminobütirik asit (GABA) ile L-histidinin birleşmesiyle sentezlenen nöroaktif bir dipeptittir. Karnozin ise beta-alanin ve histidinden, anserin ise beta-alanin ve 1-metilhistidinden meydana gelir.",
