    "subject": "Biyokimya",
    "professor": "Soycan Mızrak",
    "question": "Aşağıdakilerden hangisi fizyolojik pH'da yüksüz polar bir aminoasittir?",
    "options": [
      {
        "letter": "A",
        "text": "Aspartik asit"
      },
      {
        "letter": "B",
        "text": "Lizin"
      },
      {
        "letter": "C",
        "text": "Glutamin"
      },
      {
        "letter": "D",
        "text": "Alanin"
      },
      {
        "letter": "E",
        "text": "Fenilalanin"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "**Glutamin**, yan zincirinde amid grubu taşıyan ve fizyolojik pH'da (7.4) net yükü sıfır olan polar yüksüz bir aminoasittir. Aspartik asit negatif yüklü (asidik), lizin pozitif yüklü (bazik), alanin ve fenilalanin ise nonpolar hidrofobik aminoasitlerdir.",
