    "subject": "Biyokimya",
    "professor": "Soycan Mızrak",
    "question": "Aşağıdakilerden hangisi enzim inhibisyonunda geri dönüşümsüz olan türüne uymaz?",
    "options": [
      {
        "letter": "A",
        "text": "İnhibitör enzimin aktif bölgesine kovalent bağlanır"
      },
      {
        "letter": "B",
        "text": "Nöromediyatör asetilkolin inhibisyonu örnek verilebilir-Öğrencinin"
      },
      {
        "letter": "C",
        "text": "Tedavi amaçlı kullanılabilir"
      },
      {
        "letter": "D",
        "text": "Enzim aktif bağlanma bölgesi bozularak parçalanır"
      },
      {
        "letter": "E",
        "text": "Ürün oluşumu gerçekleşmez"
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Geri dönüşümsüz (irreversibl) inhibisyonda inhibitör, enzimin aktif merkezindeki fonksiyonel gruplarla kuvvetli kovalent bağlar kurarak veya son derece kararlı kompleks oluşturarak enzimi kalıcı inaktive eder. Bu kimyasal bir modifikasyondur; enzimin aktif merkezinin proteolitik olarak parçalanması söz konusu değildir.",
    "note": "",
