    "explanation": "Sistein aminoasidinin yıkım yolunda transaminasyon ve kükürdün uzaklaştırılması (desülfürasyon) sonucu üç karbonlu bir alfa-ketoasit olan **piruvat** meydana gelir. Bu nedenle sistein glukojenik bir aminoasittir.",
