    "explanation": "Aktin mikrofilamanları ve mikrotübüller tüm ökaryotik hücrelerde korunmuş evrensel yapılardır. **Ara filamanlar** ise doku ve hücre tipine özgü eksprese edilir (epitelde sitokeratin, mezenşimde vimentin, kasta desmin, nöronlarda nörofilaman, glia hücrelerinde GFAP).",
