    "open_answer": "",
    "explanation": "İnce bağırsak enterositlerinin ve böbrek proksimal tübül hücrelerinin apikal membranında yer alan **SGLT1/SGLT2 (Na⁺-glukoz kotransportörü)**, Na⁺ iyonu ile glukozu hücre içine aynı yönde taşıyan sekonder aktif bir **simport** mekanizması örneğidir.",
