    "answer": "B",
    "open_answer": "",
    "explanation": "Tetradotoksin (TTX), voltaj kapılı K⁺ kanallarını değil, voltaj kapılı hızlı **Na⁺ kanallarını** son derece spesifik olarak bloke eden bir toksindir; voltaj kapılı K⁺ kanallarını bloke etmek için ise tetraetilamonyum (TEA) veya 4-aminopiridin kullanılır. Bu nedenle B seçeneği yanlıştır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": ""
