    "explanation": "Kolesterol ve sfingolipidlerce zengin membran mikro-alanları olan lipid salları (lipid rafts), yapısal ve işlevsel olarak **kaveolin (I)** ve **flotillin (II)** proteinleriyle karakterizedir. Klatrin ve dinamin ise reseptör aracılı genel endositoz kılıf ve vezikül koparma proteinleridir.",
    "note": "",
