        "text": "Tek bir iyonun elektrokimyasal denge potansiyeli -> Nernst denklemi; Membrandan geçemeyen iyonlar varlığındaki denge -> Gibbs-Donnan; Birden çok iyonun geçirgenliklerine dayalı zar potansiyeli -> Goldman-Hodgkin-Katz"
