    "explanation": "Düşük yoğunluklu lipoprotein (LDL), hücre yüzeyindeki spesifik LDL reseptörlerine bağlandıktan sonra hücre zarının sitoplazmik yüzünde **klatrin** kılıflı çukurların oluşması ve vezikülleşmesiyle **klatrin aracılı endositoz** yoluyla hücre içerisine alınır.",
