    "open_answer": "",
    "explanation": "Hücre iskeleti bileşenlerinden **aktin filamentleri (mikrofilamanlar)**, globüler G-aktin monomerlerinin filamentöz F-aktine polimerizasyonu sırasında **ATP** molekülüne ve hidrolizine ihtiyaç duyar. Mikrotübüllerin polimerizasyonunda ise GTP kullanılır.",
