    "explanation": "Fokal adezyonlar, hücrelerin ekstrasellüler matrikse (fibronektin, laminin vb.) tutunmasını ve mekanik kuvvet aktarımını sağlayan dinamik bağlantılardır; bu bağlantılarda hücre zarını boydan boya kat ederek hücre dışı matrikse bağlanan transmembran reseptör ailesi **integrinler**dir.",
    "note": "",
