    "explanation": "Granüllü endoplazmik retikulum (GER) ribozomları aracılığıyla membran proteinlerini ve salgılanacak proteinleri sentezler ve lümeninde katlanmalarını sağlar. Ribozom taşımayan **Düz ER (DER)** ise fosfolipit ve steroid sentezi, kalsiyum depolanması ve detoksifikasyondan sorumludur; salgı proteinlerinin olgunlaşmasında rol almaz.",
